name: CI

on:
  pull_request:
  push:
    branches: [main]

permissions:
  contents: read

concurrency:
  group: ci-${{ github.ref }}
  cancel-in-progress: true

jobs:
  check:
    runs-on: ubuntu-latest
    timeout-minutes: 15
    steps:
      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1
      - uses: pnpm/action-setup@73e46992e05b19abd31f2f3c20e0e7370d762115 # v6.1.1
      - uses: actions/setup-node@949feb2413d6458794dcd2491c4babbbce0c15c1 # v7.1.0
        with:
          node-version-file: .node-version
          cache: pnpm
      - run: pnpm install --frozen-lockfile
      - name: Typecheck with Effect diagnostics
        run: pnpm typecheck:effect
      - run: pnpm typecheck
      - run: pnpm format:check
      - run: pnpm lint
      - run: pnpm test
      - run: pnpm --filter @surveybeat/web build
{
  "name": "@surveybeat/web",
  "private": true,
  "type": "module",
  "scripts": {
    "dev": "vite",
    "build": "vite build"
  },
  "dependencies": {
    "@base-ui/react": "catalog:",
    "@surveybeat/api": "workspace:*",
    "@surveybeat/domain": "workspace:*",
    "effect": "catalog:",
    "react": "catalog:",
    "react-dom": "catalog:"
  },
  "devDependencies": {
    "@tailwindcss/vite": "catalog:",
    "@types/react": "catalog:",
    "@types/react-dom": "catalog:",
    "tailwindcss": "catalog:",
    "vite": "catalog:"
  }
}
import tailwindcss from "@tailwindcss/vite";
import { defineConfig } from "vite";

// Two entries in one project: the app (React) and the answer page (static, no React).
export default defineConfig({
  plugins: [tailwindcss()],
  build: {
    rollupOptions: {
      // Base UI ships "use client" directives, which mean nothing in a client-only build.
      onwarn(warning, defaultHandler) {
        if (warning.code !== "MODULE_LEVEL_DIRECTIVE") defaultHandler(warning);
      },
      input: {
        app: "index.html",
        answer: "answer.html",
      },
    },
  },
});
{
  "$schema": "./node_modules/oxlint/configuration_schema.json",
  "plugins": ["typescript", "react"],
  "jsPlugins": ["./tools/oxlint-plugin-surveybeat/index.js"],
  "categories": {
    "correctness": "error"
  },
  "rules": {
    "typescript/no-floating-promises": "error",
    "typescript/no-misused-promises": "error",
    "typescript/no-explicit-any": "error",
    "typescript/consistent-type-assertions": [
      "error",
      {
        "assertionStyle": "never"
      }
    ],
    "surveybeat/domain-boundary": "error"
  },
  "overrides": [
    {
      "files": ["apps/web/src/**/*.{ts,tsx}"],
      "excludeFiles": ["**/*.test.ts", "apps/web/src/messages/**"],
      "rules": {
        "surveybeat/no-literal-ui-text": "error"
      }
    },
    {
      "files": ["**/*.test.ts"],
      "rules": {
        "typescript/consistent-type-assertions": "off"
      }
    }
  ],
  "ignorePatterns": [
    "**/dist/**",
    "**/dist-types/**",
    "**/node_modules/**",
    "tools/oxlint-plugin-surveybeat/fixtures/**",
    ".agents/**",
    ".claude/**",
    ".entire/**",
    ".factory/**",
    ".opencode/**"
  ]
}
