        logDlq: (body: string, attempts: number) =>
          sql`INSERT INTO dlq_log (body, attempts) VALUES (${body}, ${attempts})`.pipe(
            Effect.asVoid,
            Effect.orDie,
          ),
        dlqLog: () =>
          sql<{
            n: number;
            body: string;
            attempts: number;
          }>`SELECT n, body, attempts FROM dlq_log ORDER BY n`.pipe(Effect.orDie),
      };
    });
  }),
